create table if not exists public.advertisements (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, creator_id uuid not null references public.profiles(id), title text not null, image_url text, target_url text not null, placement text not null default 'sidebar' check (placement in ('header','sidebar','footer','post')), status text not null default 'draft' check (status in ('draft','published','paused','archived')), starts_at timestamptz, ends_at timestamptz, click_count bigint not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.page_views (id uuid primary key default gen_random_uuid(), organization_id uuid references public.organizations(id) on delete cascade, path text not null, referrer text, visitor_hash text, created_at timestamptz not null default now());
alter table public.advertisements enable row level security; alter table public.page_views enable row level security;
create policy "members read ads" on public.advertisements for select to authenticated using (public.is_organization_member(organization_id));
create policy "admins manage ads" on public.advertisements for all to authenticated using (public.is_organization_admin(organization_id)) with check (public.is_organization_admin(organization_id));
create policy "admins read page views" on public.page_views for select to authenticated using (public.is_organization_admin(organization_id));
create or replace function public.record_page_view(target_organization_id uuid, target_path text, target_referrer text default null, target_visitor_hash text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare view_id uuid; begin if not public.is_organization_member(target_organization_id) then raise exception 'not allowed'; end if; insert into public.page_views(organization_id,path,referrer,visitor_hash) values(target_organization_id,target_path,target_referrer,target_visitor_hash) returning id into view_id; return view_id; end; $$;
grant execute on function public.record_page_view(uuid,text,text,text) to authenticated;
